// @vitest-environment jsdom
import { act, cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'
import { afterEach, beforeEach, expect, it, vi } from 'vitest'
const stubs = vi.hoisted(() => ({ index: 0, callStart: vi.fn(), micStart: vi.fn(), callStop: vi.fn(), micStop: vi.fn(), callRows: [] as { id: number; text: string; speaker: number; isFinal: boolean; capturedAt: number }[], micRows: [] as { id: number; text: string; speaker: number; isFinal: boolean; capturedAt: number }[] }))
vi.mock('@/lib/interview/useInterviewRecorder', async (original) => {
  const actual = await original<typeof import('@/lib/interview/useInterviewRecorder')>()
  const { useState } = await import('react')
  return { ...actual, useInterviewRecorder: () => {
    const [index] = useState(() => stubs.index++)
    const call = index % 2 === 0
    return { start: call ? stubs.callStart : stubs.micStart, stop: call ? stubs.callStop : stubs.micStop, phase: 'recording', error: null, level: .2,
      getSegments: () => call ? stubs.callRows : stubs.micRows, segments: call ? stubs.callRows : stubs.micRows }
  } }
})
vi.mock('@/lib/transcription/useKeytermPrefs', () => ({ useKeytermPrefs: () => ({ keyterms: [] }) }))
vi.mock('@/lib/interview/TuningContext', () => ({ useInterviewTuning: () => ({ state: { active: { revision: 1 } } }) }))
vi.mock('./LiveAnswerCanvas', () => ({ LiveAnswerCanvas: ({ getTranscript }: { getTranscript: () => string }) => <div data-testid="answer-context">{getTranscript()}</div> }))
import { LiveInterview } from './LiveInterview'
beforeEach(() => { vi.clearAllMocks(); stubs.index = 0; stubs.callRows = []; stubs.micRows = []; stubs.callStart.mockResolvedValue(undefined); stubs.micStart.mockResolvedValue(undefined); stubs.callStop.mockImplementation(async () => stubs.callRows); stubs.micStop.mockImplementation(async () => stubs.micRows) })
afterEach(cleanup)
function configure() { fireEvent.change(screen.getByLabelText('Call service'), { target: { value: 'google-voice' } }) }
async function begin() { fireEvent.click(screen.getByRole('checkbox')); fireEvent.click(screen.getByRole('button', { name: 'Start interview' })); await waitFor(() => expect(stubs.micStart).toHaveBeenCalledOnce()) }
it('requires consent and explicitly requests tab and microphone capture without account linking', async () => {
  render(<LiveInterview visible blocked={false} onActivity={vi.fn()} onComplete={vi.fn()} />)
  configure()
  expect(stubs.callStart).not.toHaveBeenCalled()
  expect((screen.getByRole('button', { name: 'Start interview' }) as HTMLButtonElement).disabled).toBe(true)
  expect(screen.getByRole('link', { name: 'Open Google Voice' }).getAttribute('href')).toBe('https://voice.google.com/')
  expect(screen.getByText(/This is not Google account linking/)).toBeTruthy()
  await begin()
  expect(stubs.callStart).toHaveBeenCalledWith('tab', [], expect.objectContaining({ onEnded: expect.any(Function) }))
  expect(stubs.micStart).toHaveBeenCalledWith('mic', [], expect.objectContaining({ onEnded: expect.any(Function) }))
  expect(screen.getByRole('meter', { name: 'Call audio level' })).toBeTruthy()
})
it('uses per-channel names in displayed transcript, AI context and saved feedback', async () => {
  const save = vi.fn()
  const root = render(<LiveInterview visible blocked={false} onActivity={vi.fn()} onComplete={save} />)
  configure(); await begin()
  stubs.callRows = [{ id: 1, speaker: 0, text: 'How would you handle retries?', isFinal: true, capturedAt: Date.now() + 1 }]
  stubs.micRows = [{ id: 1, speaker: 0, text: 'With a bounded retry budget.', isFinal: true, capturedAt: Date.now() + 2 }]
  root.rerender(<LiveInterview visible blocked={false} onActivity={vi.fn()} onComplete={save} />)
  fireEvent.click(screen.getByText('Speaker names (2)'))
  fireEvent.change(screen.getByLabelText('Call / speaker 1'), { target: { value: 'Alex' } })
  fireEvent.change(screen.getByLabelText('Candidate microphone'), { target: { value: 'Revanth' } })
  expect(screen.getByTestId('answer-context').textContent).toContain('Alex (call): How would you handle retries?')
  expect(screen.getByTestId('answer-context').textContent).toContain('Revanth (microphone): With a bounded retry budget.')
  fireEvent.click(screen.getByRole('button', { name: 'End' }))
  await waitFor(() => expect(save).toHaveBeenCalledOnce())
  expect(save.mock.calls[0][0].transcript).toContain('Alex (call):')
  expect(save.mock.calls[0][0].captureNote).toContain('not verified identities')
})
it('stops both channels when browser sharing ends and ignores stale stop notifications', async () => {
  render(<LiveInterview visible blocked={false} onActivity={vi.fn()} onComplete={vi.fn()} />)
  configure(); await begin()
  const ended = stubs.callStart.mock.calls[0][2].onEnded
  await act(async () => ended())
  await screen.findByRole('button', { name: 'Start interview' })
  expect(stubs.callStop).toHaveBeenCalledOnce(); expect(stubs.micStop).toHaveBeenCalledOnce()
  fireEvent.click(screen.getByRole('button', { name: 'Start interview' }))
  await waitFor(() => expect(stubs.micStart).toHaveBeenCalledTimes(2))
  await act(async () => ended())
  expect(stubs.micStop).toHaveBeenCalledOnce()
})

